            ['start_time' => 648.4, 'end_time' => 660.71, 'target_text' => 'shone upon Abdullah\'s son, verses descended that echo the mercy already written in the story.', 'source_text' => 'menyinarai putera kepada Abdullah (Nabi Muhammad ﷺ), ayat-ayat diturunkan yang menggemakan kembali rahmat yang sememangnya telah tertulis dalam kisah ini:', 'order' => 76],
