            ['start_time' => 711.12, 'end_time' => 718.47, 'target_text' => 'Indeed with hardship comes ease and indeed with hardship comes ease. Zum', 'source_text' => '"Kerana sesungguhnya bersama kesukaran ada kemudahan, sesungguhnya bersama kesukaran ada kemudahan." (Surah Asy-Syarh: 5-6). Zamzam', 'order' => 83],
